import { createServer, type ServerResponse } from 'node:http';
import { once } from 'node:events';
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';

/** Generated by absolute offset: chunks and ranged requests have identical bytes. */
export function fixtureBytes(offset: number, length: number): Uint8Array {
  const data = new Uint8Array(length);
  for (let i = 0; i < length; i++) {
    const position = offset + i;
    data[i] = (position * 31 + Math.floor(position / 251) * 17) % 256;
  }
  return data;
}

export function fixtureHash(size: number): string {
  const hash = createHash('sha256');
  for (let offset = 0; offset < size; offset += 64 * 1024) {
    hash.update(fixtureBytes(offset, Math.min(64 * 1024, size - offset)));
  }
  return hash.digest('hex');
}

export interface FixtureStats {
  requests: number;
  rangeRequests: number;
  active: number;
  maxActive: number;
  bytes: number;
  paths: string[];
  ranges: string[];
  ifRanges: string[];
}

export async function startFixture() {
  const media = new Map(
    await Promise.all(
      [
        'vod.m3u8',
        'source.mp4',
        'init.mp4',
        'part-0.m4s',
        'part-1.m4s',
        'part-2.m4s',
        'part-3.m4s',
      ].map(
        async (name) =>
          [name, await readFile(new URL('./media/' + name, import.meta.url))] as const,
      ),
    ),
  );
  const stats: FixtureStats = {
    requests: 0,
    rangeRequests: 0,
    active: 0,
    maxActive: 0,
    bytes: 0,
    paths: [],
    ranges: [],
    ifRanges: [],
  };
  const attempts = new Map<string, number>();
  const versions = new Map<string, number>();
  const outages = new Set<string>();
  const rangeFailures = new Map<string, number>();
  const server = createServer(async (req, res) => {
    stats.requests++;
    const url = new URL(req.url ?? '/', 'http://fixture.invalid');
    const route = url.pathname;
    stats.paths.push(route);
    if (outages.has(route)) {
      res.writeHead(503, { 'Retry-After': '0' }).end();
      return;
    }
    if (route.startsWith('/hls/')) {
      let bytes = media.get(route.slice(5));
      if (route === '/hls/master.m3u8')
        bytes = Buffer.from(
          '#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=200000,RESOLUTION=160x90,CODECS="avc1.42E01E,mp4a.40.2"\nvod.m3u8\n',
        );
      if (route === '/hls/cross.m3u8')
        bytes = Buffer.from(
          media
            .get('vod.m3u8')!
            .toString()
            .replace(
              'part-0.m4s',
              `http://cdn.example.com:${(server.address() as { port: number }).port}/hls/part-0.m4s`,
            ),
        );
      if (!bytes) {
        res.writeHead(404).end();
        return;
      }
      const range = req.headers.range?.match(/^bytes=(\d+)-(\d+)$/);
      const start = range ? Number(range[1]) : 0,
        end = range ? Number(range[2]) : bytes.length - 1;
      if (start < 0 || end >= bytes.length || start > end) {
        res.writeHead(416).end();
        return;
      }
      res.setHeader(
        'Content-Type',
        route.endsWith('.m3u8') ? 'application/vnd.apple.mpegurl' : 'video/mp4',
      );
      res.setHeader('ETag', `"${createHash('sha256').update(bytes).digest('hex')}"`);
      res.setHeader('Accept-Ranges', 'bytes');
      res.setHeader('Content-Length', end - start + 1);
      res.setHeader('Access-Control-Allow-Origin', '*');
      res.setHeader('Access-Control-Expose-Headers', '*');
      if (range) {
        res.statusCode = 206;
        res.setHeader('Content-Range', `bytes ${start}-${end}/${bytes.length}`);
        stats.ranges.push(req.headers.range!);
        stats.rangeRequests++;
      }
      if (req.method === 'HEAD') {
        res.end();
        return;
      }
      const delay = Number(url.searchParams.get('delay') ?? 0),
        chunk = delay ? 256 : 65536;
      for (let offset = start; offset <= end && !res.destroyed; offset += chunk) {
        const data = bytes.subarray(offset, Math.min(end + 1, offset + chunk));
        stats.bytes += data.length;
        if (!res.write(data)) await waitDrain(res);
        if (delay) await new Promise((resolve) => setTimeout(resolve, delay));
      }
      res.end();
      return;
    }
    if (route === '/capture-page') {
      const port = (server.address() as { port: number }).port;
      res.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Set-Cookie': 'fixture_auth=1; Path=/; SameSite=Lax',
      }).end(`<!doctype html><title>Flux capture fixture</title>
        <a id="normal" href="/file.zip?size=1048576&delay=2">Normal ZIP</a>
        <a id="download-attribute" href="/endpoint?size=1048576&delay=2" download="named.bin">Explicit download</a>
        <a id="cross-origin" href="http://cdn.example.com:${port}/cross.zip?size=1048576&delay=2">CDN file</a>
        <a id="redirect" href="/redirect?filename=redirect.zip&size=1048576">Redirected file</a>
        <a id="excluded" href="/excluded.zip?size=131072">Excluded ZIP</a>
        <button id="native" onclick="location.href='/attachment?size=2097152&delay=30'">Generated GET download</button>
        <button id="authenticated" onclick="location.href='/auth-browser?size=2097152&delay=30'">Authenticated download</button>
        <a id="authenticated-link" href="/auth-browser?filename=private.zip&size=1048576&delay=5">Authenticated ZIP link</a>
        <form method="post" action="/post-file?size=131072"><button id="post">POST download</button></form>`);
      return;
    }
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Expose-Headers', '*');
    const size = Number(url.searchParams.get('size') ?? 3 * 1024 * 1024);
    if (!Number.isSafeInteger(size) || size < 0 || size > 20 * 1024 ** 3) {
      res.writeHead(400).end('Invalid size');
      return;
    }
    if (route === '/redirect') {
      res.writeHead(302, { Location: `/range${url.search}` }).end();
      return;
    }
    if (route === '/redirect-to') {
      res.writeHead(302, { Location: url.searchParams.get('to') ?? '/range' }).end();
      return;
    }
    if (route === '/redirect-loop') {
      res.writeHead(302, { Location: '/redirect-loop' }).end();
      return;
    }
    if (route === '/reject-range' && req.headers.range) {
      res.writeHead(403).end();
      return;
    }
    if (route === '/auth-browser' && !req.headers.cookie?.includes('fixture_auth=1')) {
      res.writeHead(401).end();
      return;
    }
    if (route === '/redirect-private') {
      res.writeHead(302, { Location: 'http://127.0.0.2/private' }).end();
      return;
    }
    if (route === '/auth' && req.headers.authorization !== 'Bearer fixture') {
      res.writeHead(401).end();
      return;
    }
    if (route === '/expiring' && Date.now() > Number(url.searchParams.get('expires') ?? 0)) {
      res.writeHead(403).end();
      return;
    }
    const probe = req.headers.range === 'bytes=0-0' || req.method === 'HEAD';
    const failureFrom = rangeFailures.get(route);
    const requestedStart = Number(req.headers.range?.match(/^bytes=(\d+)-/)?.[1]);
    if (!probe && failureFrom !== undefined && requestedStart >= failureFrom) {
      res.writeHead(503, { 'Retry-After': '0' }).end();
      return;
    }
    const version = route === '/changing-etag' && !probe ? 2 : (versions.get(route) ?? 1);
    const etag = `"fixture-v${version}"`;
    res.setHeader('ETag', etag);
    res.setHeader('Last-Modified', 'Mon, 01 Jan 2024 00:00:00 GMT');
    res.setHeader('Content-Type', 'application/octet-stream');
    res.setHeader('Content-Disposition', "attachment; filename*=UTF-8''fixture-%E2%9C%93.bin");
    res.setHeader('Accept-Ranges', route === '/no-range' ? 'none' : 'bytes');
    let start = 0,
      end = size - 1,
      partial = false;
    const range = req.headers.range;
    const match = range?.match(/^bytes=(\d+)-(\d*)$/);
    if (range) {
      stats.rangeRequests++;
      stats.ranges.push(range);
    }
    if (req.headers['if-range']) stats.ifRanges.push(String(req.headers['if-range']));
    if (
      match &&
      !['/ignored-range', '/no-range', '/no-length', '/single-disconnect', '/single-slow'].includes(
        route,
      ) &&
      (!req.headers['if-range'] || req.headers['if-range'] === etag)
    ) {
      start = Number(match[1]);
      end = Math.min(size - 1, match[2] ? Number(match[2]) : size - 1);
      partial = true;
      if (start > end || start >= size) {
        res.writeHead(416, { 'Content-Range': `bytes */${size}` }).end();
        return;
      }
    }
    if (!probe) {
      const count = (attempts.get(route) ?? 0) + 1;
      attempts.set(route, count);
      if ((route === '/429' || route === '/503') && count === 1) {
        res.writeHead(route === '/429' ? 429 : 503, { 'Retry-After': '0' }).end();
        return;
      }
    }
    if (partial)
      res.setHeader(
        'Content-Range',
        `bytes ${(route === '/bad-range' && !probe) || route === '/probe-invalid' ? start + 1 : start}-${end}/${size}`,
      );
    if (route === '/encoded') res.setHeader('Content-Encoding', 'gzip');
    if (route !== '/no-length') res.setHeader('Content-Length', Math.max(0, end - start + 1));
    res.statusCode = partial ? 206 : 200;
    if (req.method === 'HEAD' || size === 0) {
      res.end();
      return;
    }
    stats.active++;
    stats.maxActive = Math.max(stats.active, stats.maxActive);
    let finished = false;
    const finish = () => {
      if (!finished) {
        stats.active--;
        finished = true;
      }
    };
    res.once('close', finish);
    res.once('finish', finish);
    const disconnect =
      !probe &&
      ((['/disconnect', '/single-disconnect'].includes(route) && attempts.get(route) === 1) ||
        route === '/truncated');
    const stopAt = disconnect ? start + Math.max(1, Math.floor((end - start + 1) / 2)) : end + 1;
    const slow = ['/slow', '/capped', '/single-slow'].includes(route);
    const chunkSize = slow ? 16 * 1024 : 64 * 1024;
    const delay = Number(url.searchParams.get('delay') ?? (slow ? 8 : 0));
    try {
      for (let offset = start; offset < stopAt && !res.destroyed; offset += chunkSize) {
        const bytes = fixtureBytes(offset, Math.min(chunkSize, stopAt - offset));
        if (
          (route === '/corrupt' || version > 1) &&
          offset <= 12345 &&
          offset + bytes.length > 12345
        )
          bytes[12345 - offset]! ^= 0xff;
        stats.bytes += bytes.length;
        if (!res.write(bytes)) await waitDrain(res);
        if (delay && !probe && offset + bytes.length < stopAt)
          await new Promise<void>((resolve) => setTimeout(resolve, delay));
      }
      if (disconnect) res.destroy();
      else res.end();
    } catch {
      res.destroy();
    }
  });
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  const address = server.address();
  if (!address || typeof address === 'string') throw new Error('Fixture failed to listen.');
  return {
    url: `http://127.0.0.1:${address.port}`,
    stats,
    reset() {
      stats.requests = stats.rangeRequests = stats.bytes = stats.maxActive = 0;
      stats.paths.length = stats.ranges.length = stats.ifRanges.length = 0;
      attempts.clear();
    },
    setVersion(route: string, version: number) {
      versions.set(route, version);
    },
    setOutage(route: string, active: boolean) {
      if (active) outages.add(route);
      else outages.delete(route);
    },
    setRangeFailure(route: string, from: number | null) {
      if (from === null) rangeFailures.delete(route);
      else rangeFailures.set(route, from);
    },
    async close() {
      server.closeAllConnections();
      await new Promise<void>((resolve, reject) =>
        server.close((error) => (error ? reject(error) : resolve())),
      );
    },
  };
}

function waitDrain(response: ServerResponse): Promise<void> {
  return new Promise((resolve) => {
    const done = () => {
      response.off('drain', done);
      response.off('close', done);
      resolve();
    };
    response.once('drain', done);
    response.once('close', done);
  });
}
